<div class="card"><h1>User Management</h1><input id="adminUserQ" onkeyup="adminUserSearch()" placeholder="Search users by name, email, role"><table><thead><tr><th>User</th><th>Role</th><th>Active</th><th>Actions</th></tr></thead><tbody id="adminUsersTable"><?php foreach($rows as $r): ?><tr><td><?= e($r['name']) ?><br><?= e($r['email']) ?></td><td><?= e($r['role']) ?></td><td><?= e($r['is_active']) ?></td><td><form method="post"><input type="hidden" name="action" value="active"><input type="hidden" name="id" value="<?= $r['id'] ?>"><input type="hidden" name="is_active" value="<?= $r['is_active']?0:1 ?>"><button><?= $r['is_active']?'Deactivate':'Reactivate' ?></button></form><form method="post"><input type="hidden" name="action" value="role"><input type="hidden" name="id" value="<?= $r['id'] ?>"><select name="role"><option value="buyer">Buyer</option><option value="moderator">Moderator</option><option value="admin">Admin</option></select><button>Change Role</button></form></td></tr><?php endforeach; ?></tbody></table></div>
